/bin/zsh -lc "node --input-type=module <<'EOF'
import { readFile, writeFile } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'
import { createServer } from 'vite'
import { featureFlags } from './packages/plugin/dist/index.js'

const root = fileURLToPath(new URL('./examples/consumer/', import.meta.url))
const source = fileURLToPath(new URL('./examples/consumer/flags.json', import.meta.url))
await writeFile(source, JSON.stringify({ checkoutV2: true, theme: 'dark', SERVER_TOKEN: 'server-token-for-eval' }, null, 2) + '\\n')
const original = await readFile(source, 'utf8')
const server = await createServer({
  root,
  configFile: false,
  logLevel: 'silent',
  server: { middlewareMode: true },
  plugins: [featureFlags({ source, expose: ['checkoutV2', 'theme'] })],
})

server.watcher.on('all', (event, path) => {
  if (path.includes('flags.json')) console.log('watcher', event, path)
})

try {
  const first = await server.ssrLoadModule('/src/flags.ts')
  console.log('first', first.flags)
  const changed = JSON.stringify({ checkoutV2: false, theme: 'light', SERVER_TOKEN: 'server-token-for-eval' }, null, 2) + '\\n'
  await writeFile(source, changed)
  console.log('wrote file')
  await new Promise((resolve) => setTimeout(resolve, 1500))
  const second = await server.ssrLoadModule('/src/flags.ts')
  console.log('second', second.flags)
} finally {
  await writeFile(source, original)
  await server.close()
}
EOF"

