import { watch } from 'node:fs'
import { readFile } from 'node:fs/promises'
import { isAbsolute, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

import type { HmrContext, Plugin, ResolvedConfig, ViteDevServer } from 'vite'

export type FeatureFlagValue = boolean | number | string | null

export interface FeatureFlagRegistry {
  [key: string]: FeatureFlagValue
}

export type ResolvedFeatureFlagRegistry<TRegistry extends FeatureFlagRegistry> =
  keyof TRegistry extends never ? Record<string, FeatureFlagValue> : TRegistry

export type FeatureFlags<TRegistry extends FeatureFlagRegistry = FeatureFlagRegistry> = Readonly<
  ResolvedFeatureFlagRegistry<TRegistry>
>

export interface FeatureFlagsOptions<TRegistry extends FeatureFlagRegistry = FeatureFlagRegistry> {
  source: string | URL
  expose: readonly (keyof TRegistry & string)[]
}

const PLUGIN_NAME = 'feature-flags'
const VIRTUAL_MODULE_ID = 'virtual:feature-flags'
const RESOLVED_VIRTUAL_MODULE_ID = `\0${VIRTUAL_MODULE_ID}`
const EMPTY_MAP = {
  version: 3 as const,
  sources: [],
  names: [],
  mappings: '',
  sourcesContent: [],
}
const SECRET_LIKE_KEY = /(secret|token|password|private[_-]?key|api[_-]?key)/i

interface CachedModule {
  code: string
  flags: Record<string, FeatureFlagValue>
  sourceText: string
}

function normalizeSourcePath(source: string | URL): string {
  return source instanceof URL ? fileURLToPath(source) : source
}

function createDiagnostic(message: string, nextStep: string): Error {
  return new Error(`[${PLUGIN_NAME}] ${message}\nFix: ${nextStep}`)
}

function describeJsonValue(value: unknown): string {
  if (value === null) return 'null'
  if (Array.isArray(value)) return 'array'
  return typeof value
}

function isFeatureFlagValue(value: unknown): value is FeatureFlagValue {
  return value === null || ['boolean', 'number', 'string'].includes(typeof value)
}

function validateOptions(sourcePath: string, expose: readonly string[]): void {
  if (expose.length === 0) {
    throw createDiagnostic(
      `No public flags were configured for ${JSON.stringify(sourcePath)}.`,
      'Pass at least one key in the "expose" option.',
    )
  }

  const duplicates = expose.filter((key, index) => expose.indexOf(key) !== index)
  if (duplicates.length > 0) {
    throw createDiagnostic(
      `Duplicate public flags were configured: ${duplicates.map((key) => JSON.stringify(key)).join(', ')}.`,
      'Remove duplicate entries from the "expose" option.',
    )
  }
}

async function loadPublicFlags(
  sourcePath: string,
  expose: readonly string[],
): Promise<CachedModule> {
  const sourceText = await readFile(sourcePath, 'utf8')

  let parsed: unknown
  try {
    parsed = JSON.parse(sourceText)
  } catch (error) {
    const detail = error instanceof Error ? error.message : String(error)
    throw createDiagnostic(
      `Could not parse JSON in ${JSON.stringify(sourcePath)}. ${detail}`,
      'Fix the JSON syntax in the source file.',
    )
  }

  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    throw createDiagnostic(
      `${JSON.stringify(sourcePath)} must contain a JSON object at the top level.`,
      'Change the file to an object whose keys are the available flags.',
    )
  }

  const record = parsed as Record<string, unknown>
  const flags: Record<string, FeatureFlagValue> = {}

  for (const key of expose) {
    if (!(key in record)) {
      throw createDiagnostic(
        `Configured public flag ${JSON.stringify(key)} does not exist in ${JSON.stringify(sourcePath)}.`,
        `Add ${JSON.stringify(key)} to the source file or remove it from "expose".`,
      )
    }

    if (SECRET_LIKE_KEY.test(key)) {
      throw createDiagnostic(
        `Refusing to expose ${JSON.stringify(key)} because its name looks secret-like.`,
        `Keep ${JSON.stringify(key)} on the server and expose a non-sensitive derived flag instead.`,
      )
    }

    const value = record[key]
    if (!isFeatureFlagValue(value)) {
      throw createDiagnostic(
        `Public flag ${JSON.stringify(key)} in ${JSON.stringify(sourcePath)} must be a primitive JSON value, received ${describeJsonValue(value)}.`,
        `Flatten ${JSON.stringify(key)} to a string, number, boolean, or null before exposing it.`,
      )
    }

    flags[key] = value
  }

  const code = [
    `export const flags = Object.freeze(${JSON.stringify(flags)});`,
    'export default flags;',
  ].join('\n')

  return { code, flags, sourceText }
}

export function featureFlags<TRegistry extends FeatureFlagRegistry = FeatureFlagRegistry>(
  options: FeatureFlagsOptions<TRegistry>,
): Plugin {
  const configuredSourcePath = normalizeSourcePath(options.source)
  const expose = [...options.expose]
  let config: ResolvedConfig | undefined
  let server: ViteDevServer | undefined
  let cachedModule: CachedModule | undefined
  let sourceWatcher: ReturnType<typeof watch> | undefined
  let sourcePath = configuredSourcePath

  validateOptions(configuredSourcePath, expose)

  async function getCachedModule(): Promise<CachedModule> {
    const nextModule = await loadPublicFlags(sourcePath, expose)
    if (cachedModule && cachedModule.sourceText === nextModule.sourceText) {
      return cachedModule
    }

    cachedModule = nextModule
    return nextModule
  }

  function invalidateAllModules(): void {
    if (!server) return

    for (const environment of Object.values(server.environments)) {
      environment.moduleGraph.invalidateAll()
    }
  }

  return {
    name: PLUGIN_NAME,
    enforce: 'pre',
    configResolved(resolvedConfig) {
      config = resolvedConfig
      sourcePath = isAbsolute(configuredSourcePath)
        ? configuredSourcePath
        : resolve(resolvedConfig.root, configuredSourcePath)
    },
    configureServer(configuredServer) {
      server = configuredServer
      configuredServer.watcher.add(sourcePath)
      sourceWatcher?.close()
      sourceWatcher = watch(sourcePath, { persistent: false }, () => {
        cachedModule = undefined
        invalidateAllModules()
        configuredServer.watcher.emit('change', sourcePath)
      })
    },
    async buildStart() {
      await getCachedModule()
    },
    resolveId(id) {
      if (id === VIRTUAL_MODULE_ID) {
        return RESOLVED_VIRTUAL_MODULE_ID
      }
      return null
    },
    async load(id) {
      if (id !== RESOLVED_VIRTUAL_MODULE_ID) {
        return null
      }

      this.addWatchFile(sourcePath)

      const module = await getCachedModule()
      return {
        code: module.code,
        map: EMPTY_MAP,
      }
    },
    handleHotUpdate(context: HmrContext) {
      if (context.file !== sourcePath) {
        return
      }

      cachedModule = undefined
      invalidateAllModules()
    },
    buildEnd(error) {
      if (error || !config || config.command !== 'build') {
        return
      }
      cachedModule = undefined
    },
    closeBundle() {
      sourceWatcher?.close()
      sourceWatcher = undefined
    },
  }
}

