type FeatureFlagTypesValue = boolean | number | string | null

interface FeatureFlagTypes {}

type ResolvedFeatureFlagTypes = keyof FeatureFlagTypes extends never
  ? Record<string, FeatureFlagTypesValue>
  : FeatureFlagTypes

declare module 'virtual:feature-flags' {
