import assert from 'node:assert/strict'
import { execFile } from 'node:child_process'
import { mkdir, mkdtemp, rename, rm, writeFile } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { promisify } from 'node:util'

const run = promisify(execFile)
const root = fileURLToPath(new URL('../', import.meta.url))
const temporaryConsumer = await mkdtemp(
  join(tmpdir(), 'frontend-architect-packed-consumer-'),
)
const npmCache = join(temporaryConsumer, '.npm-cache')
const npmEnv = { ...process.env, npm_config_cache: npmCache }

try {
  const { stdout } = await run(
    'npm',
    [
      'pack',
      '--json',
      '--workspace',
      '@frontend-architect-eval/feature-flags',
      '--pack-destination',
      temporaryConsumer,
    ],
    { cwd: root, env: npmEnv },
  )
  const [manifest] = JSON.parse(stdout)
  const files = new Set(manifest.files.map(({ path }) => path))

  for (const expected of [
    'dist/index.js',
    'dist/index.js.map',
    'dist/index.d.ts',
    'dist/virtual.d.ts',
  ]) {
    assert.ok(files.has(expected), `packed package is missing ${expected}`)
  }

  const scopeDirectory = join(temporaryConsumer, 'node_modules', '@frontend-architect-eval')
  const extractedDirectory = join(scopeDirectory, 'package')
  const installedPackageDirectory = join(scopeDirectory, 'feature-flags')

  await mkdir(scopeDirectory, { recursive: true })
  await run('tar', ['-xzf', join(temporaryConsumer, manifest.filename), '-C', scopeDirectory], {
    cwd: temporaryConsumer,
  })
  await rename(extractedDirectory, installedPackageDirectory)

  await writeFile(
    join(temporaryConsumer, 'package.json'),
    JSON.stringify({ private: true, type: 'module' }),
  )
  await writeFile(
    join(temporaryConsumer, 'verify.mjs'),
    [
      "import assert from 'node:assert/strict'",
      "import { featureFlags } from '@frontend-architect-eval/feature-flags'",
      "const plugin = featureFlags({ source: new URL('./flags.json', import.meta.url), expose: ['checkoutV2'] })",
      "assert.equal(typeof plugin, 'object')",
      "assert.equal(typeof plugin.resolveId, 'function')",
      "assert.equal(typeof plugin.load, 'function')",
    ].join('\n'),
  )
  await run(process.execPath, ['verify.mjs'], { cwd: temporaryConsumer, env: npmEnv })
} finally {
  await rm(temporaryConsumer, { recursive: true, force: true })
}
